int def scoreAge(int:age) {
    if (age >= 25 && age <= 50) {
        return 15;
    } else if (age >= 51 && age <= 60) {
        return 12;
    } else if (age >= 18 && age <= 24) {
        return 8;
    } else if (age >= 61 && age <= 64) {
        return 6;
    } else {
        return 3;
    }
}


