    if (annualIncome >= 500000.0) {
        return 15;
    } else if (annualIncome >= 200000.0) {
        return 12;
    } else if (annualIncome >= 100000.0) {
        return 8;
    } else if (annualIncome >= 50000.0) {
        return 4;
    } else {
        return 2;
    }
}


