int def scoreTolerance(int:riskToleranceRank) {
    if (riskToleranceRank >= 5) {
        return 30;
    } else if (riskToleranceRank == 4) {
        return 24;
    } else if (riskToleranceRank == 3) {
        return 18;
    } else if (riskToleranceRank == 2) {
        return 10;
    } else {
        return 5;
    }
}


boolean def needConfirm(int:maturityScore, int:productRiskRank, boolean:elderly) {
    boolean confirm = false;
    if (maturityScore < 50) {
        if (productRiskRank >= 3) {
            confirm = true;
        }
    }
    if (elderly) {
        if (productRiskRank >= 3) {
            confirm = true;
        }
    }
    return confirm;
}


int def rankGap(int:riskToleranceRank, int:productRiskRank) {
    return productRiskRank - riskToleranceRank;
}
